export type UiSkinFamily = keyof typeof UI_SKIN_MANIFEST;

export type UiControlState = 'idle' | 'pressed' | 'disabled';
export function uiButtonSkin(tone: UiTone, size: UiControlSize, shape: UiShape, state: UiControlState): UiSkinEntry {
  return UI_SKIN_MANIFEST.button[`${tone}.${size}.${shape}.${state}`];
}
export function uiToneFrameSkin(tone: UiTone): UiSkinEntry {
  return UI_SKIN_MANIFEST.frame[`${tone}.idle`];
}

/** The source supplies left/down tags. Right/up are explicit rotated selections. */
export function uiDirectionalTagSkin(tone: Exclude<UiTone, 'muted'>, direction: 'left' | 'right' | 'up' | 'down'): UiSkinEntry {
  const entry = UI_SKIN_MANIFEST.feedback[`${tone}.tag.${direction === 'left' || direction === 'right' ? 'left_round' : 'down_left'}`];
  return direction === 'right' || direction === 'up' ? { ...entry, quarterTurns: 2 } : entry;
}
